macro.command:
// 专长物品自带 OnUse 宏。挂载 preAttackRoll、preCheckHits、postDamageRoll、postActiveEffects。
const pass = args[0].macroPass;
const attacker = macroItem.actor;
const attack = workflow.item;
const bonus = attack.getFlag("world", "greatWeaponMasterBonus");
const combat = game.combat;
const ownTurn = combat?.combatant?.tokenId === workflow.tokenId;

// 收藏的效用物品：先选原武器，取消时不消耗附赠动作。
if (pass === "preItemRoll" && bonus) {
  if (workflow.targets.size !== 1) {
    ui.notifications.warn("请指定一个附赠攻击目标。");
    return false;
  }
  const weapons = attacker.items.filter(i => i.type === "weapon" && i.system.equipped
    && i.system.activities.some(a => a.type === "attack" && a.getActionType() === "mwak"));
  if (!weapons.length) return false;
  const selectedWeapon = weapons.length === 1 ? weapons[0] : await dnd5eClasspack.dialogUtils.selectDocumentDialog(
    "巨武器大师 · 选择武器", "", weapons,
    { userId: dnd5eClasspack.firstOwner(attacker, true) }
  );
  if (!selectedWeapon) return false;
  workflow.greatWeaponMasterWeapon = selectedWeapon.id;
  return;
}

if (pass === "postActiveEffects" && bonus) {
  if (workflow.greatWeaponMasterUsed) return;
  workflow.greatWeaponMasterUsed = true;
  const selectedWeapon = attacker.items.get(workflow.greatWeaponMasterWeapon);
  if (selectedWeapon) await MidiQOL.completeItemUse(selectedWeapon, {
    chooseActivity: true,
    midiOptions: {
      targetUuids: [...workflow.targets].map(t => t.document.uuid),
      workflowOptions: {
        notBonusAction: true, notReaction: true, greatWeaponMasterAttack: true,
        attackMode: selectedWeapon.system.attackModes.find(m => ["oneHanded", "twoHanded"].includes(m.value))?.value
      }
    }
  });
  await fromUuidSync(attack.getFlag("dnd5e", "dependentOn"))?.delete();
  return;
}

if (attack.type !== "weapon" || workflow.activity.type !== "attack") return;
const melee = workflow.activity.getActionType(workflow.attackMode) === "mwak";
const heavy = attack.system.properties.has("hvy") && attack.system.proficiencyMultiplier > 0;

if (pass === "preAttackRoll") {
  const activity = workflow.activity;
  const previous = workflow.greatWeaponMaster;
  const originalBonus = previous?.activity === activity ? previous.originalBonus : activity.attack.bonus;
  const originalDialog = previous?.activity === activity ? previous.originalDialog : activity.midiProperties.forceRollDialog;
  activity.attack.bonus = originalBonus;
  activity.midiProperties.forceRollDialog = originalDialog;
  // 每次攻击都重新询问，不使用可重置的 attackRollCount 作为技能使用限制。
  workflow.greatWeaponMaster = { activity, originalBonus, originalDialog, enabled: false };
  if (heavy && workflow.activity.getActionType() === "mwak") workflow.greatWeaponMaster.enabled = await dnd5eClasspack.dialogUtils.confirm(
    "巨武器大师", "<p>攻击 −5，命中伤害 +10。</p>",
    { userId: dnd5eClasspack.firstOwner(attacker, true) }
  );
  const state = workflow.greatWeaponMaster;
  if (state.enabled) {
    activity.attack.bonus = originalBonus ? `(${originalBonus}) - 5[巨武器大师]` : "-5[巨武器大师]";
  }
  return;
}

const state = workflow.greatWeaponMaster;
if (!state) return;
if (pass === "preCheckHits") {
  if ((state.enabled || workflow.workflowOptions.greatWeaponMasterAttack) && !melee) {
    workflow.aborted = true;
    ui.notifications.warn("巨武器大师攻击必须使用近战模式。");
    return;
  }
  if (!heavy || !melee) {
    state.enabled = false;
  }
} else if (pass === "postDamageRoll") {
  if (!state.enabled || state.damageCount === workflow.damageRollCount) return;
  const rolls = [...workflow.damageRolls];
  if (!rolls.length) return;
  rolls[0] = MidiQOL.addRollTo(rolls[0], await new Roll("10[巨武器大师]").evaluate());
  await workflow.setDamageRolls(rolls);
  state.damageCount = workflow.damageRollCount;
} else if (pass === "postActiveEffects") {
  const damages = workflow.damageList?.length ? workflow.damageList : [workflow.damageItem];
  const killed = damages.some(d => d?.wasHit !== false && d?.oldHP > 0 && d.newHP <= 0 && d.hpDamage > 0);
  if (!melee || (combat?.started && !ownTurn) || (!workflow.isCritical && !killed)) return;
  if (state.created || attacker.items.some(i => i.getFlag("world", "greatWeaponMasterBonus")
    && i.system.uses.value > 0)) return;
  state.created = true;

  const [effect] = await attacker.createEmbeddedDocuments("ActiveEffect", [{
    name: "巨武器大师：附赠攻击", type: "base", img: macroItem.img,
    origin: macroItem.uuid, duration: { expiry: "targetEnd" }
  }]);
  const id = foundry.utils.randomID();
  const [temporary] = await attacker.createEmbeddedDocuments("Item", [{
    name: "巨武器大师：附赠攻击", type: "feat", img: macroItem.img, effects: [],
    system: {
      uses: { max: "1", spent: 0, recovery: [] },
      activities: { [id]: {
        _id: id, name: "附赠攻击", type: "utility",
        activation: { type: "bonus", cost: 1 },
        target: { affects: { type: "creature", count: "1" } },
        consumption: { targets: [{ type: "itemUses", target: "", value: "1" }] }
      } }
    },
    flags: {
      world: { greatWeaponMasterBonus: true }, dnd5e: { dependentOn: effect.uuid },
      "midi-qol": { onUseMacroName: `[preItemRoll]ItemMacro.${macroItem.uuid},[postActiveEffects]ItemMacro.${macroItem.uuid}` }
    }
  }]);
  await attacker.system.addFavorite({ type: "item", id: foundry.utils.buildRelativeUuid(temporary, attacker) });
  await foundry.documents.ChatMessage.implementation.create({
    speaker: foundry.documents.ChatMessage.getSpeaker({ actor: attacker, token: workflow.token?.document }),
    content: await foundry.applications.ux.TextEditor.enrichHTML(
      `<div class="chat-card"><p><strong>巨武器大师：附赠攻击可用</strong></p>
      <p>可用附赠动作发动一次近战武器攻击。</p>
      <p>@UUID[${temporary.uuid}]{附赠攻击} 已加入角色收藏。</p></div>`,
      { relativeTo: attacker }
    )
  });
}
